 const [customer,setCustomer]=useState(initialValues?.newCustomer?'new':initialValues?.customerId??initialCustomer),[name,setName]=useState(initialValues?.newCustomer?.name??''),[email,setEmail]=useState(initialValues?.newCustomer?.email??''),[phone,setPhone]=useState(initialValues?.newCustomer?.phone??''),[title,setTitle]=useState(initialValues?.title??''),[owner,setOwner]=useState(initialValues?.primaryOwnerId===null?'unassigned':initialValues?.primaryOwnerId??''),[team,setTeam]=useState<string[]>(initialValues?.teamUserIds??[]),[service,setService]=useState(initialValues?.service??''),[location,setLocation]=useState(initialValues?.location??''),[description,setDescription]=useState(initialValues?.description??''),[date,setDate]=useState(initialValues?.scheduledDate??''),[window,setWindow]=useState(initialValues?.arrivalWindow??''),[deadline,setDeadline]=useState(initialValues?.completionDeadline??''),[review,setReview]=useState(initialReview),[duplicateAccepted,setDuplicateAccepted]=useState(false);
