'use client';
import {useId,useRef,useState,type ReactNode} from 'react';import Dialog from '@mui/material/Dialog';import {FormFeedback} from '@salesmora/ui';import {jobButton,jobPrimary} from '../job-ui';import {copy} from './job-dialog.data';
export type JobDialogProps={open:boolean;title:string;description:string;children:ReactNode;confirmLabel:string;confirmDisabled?:boolean;pending?:boolean;error?:string;conflict?:boolean;onReload?:()=>void;closeOnSubmit?:boolean;onClose:()=>void;onSubmit:()=>void|Promise<void>};
export function JobDialog({open,title,description,children,confirmLabel,confirmDisabled,pending,error,conflict=false,onReload,closeOnSubmit=true,onClose,onSubmit}:JobDialogProps){
 const id=useId(),[working,setWorking]=useState(false),[failure,setFailure]=useState(''),inFlight=useRef(false),busy=!!pending||working;
 const close=()=>{if(!busy&&!inFlight.current)onClose();};
 return <Dialog open={open} fullWidth maxWidth="sm" scroll="paper" onClose={close} slotProps={{backdrop:{className:'bg-ink/50'},paper:{tabIndex:busy?0:-1,'aria-labelledby':id,'aria-describedby':`${id}-description`,className:'m-3 min-w-0 rounded-2xl bg-paper text-ink focus-visible:focus-ring sm:m-8'}}}><form className="min-w-0 p-5 sm:p-8" onSubmit={async e=>{e.preventDefault();if(busy||conflict||confirmDisabled||inFlight.current)return;inFlight.current=true;setWorking(true);setFailure('');try{await onSubmit();if(closeOnSubmit)onClose();}catch{setFailure(copy.error);}finally{inFlight.current=false;setWorking(false);}}}><header className="mb-6 flex items-start justify-between gap-3"><div className="min-w-0"><h2 id={id} className="m-0 text-2xl font-semibold wrap-anywhere">{title}</h2><p id={`${id}-description`} className="mb-0 mt-3 text-sm leading-6 text-muted">{description}</p></div><button type="button" disabled={busy} onClick={close} className={`${jobButton} shrink-0`}>{copy.close}</button></header>{(error||failure||conflict)&&<div className="mb-4"><FormFeedback kind="error" message={error||failure||copy.conflict}/></div>}{conflict&&onReload&&<button type="button" className={`${jobButton} mb-4`} disabled={busy} onClick={onReload}>{copy.reload}</button>}<fieldset disabled={busy} className="m-0 grid min-w-0 gap-4 border-0 p-0">{children}</fieldset><footer className="mt-6 flex flex-wrap justify-end gap-3"><button type="button" disabled={busy} onClick={close} className={jobButton}>{copy.cancel}</button><button type="submit" disabled={busy||conflict||confirmDisabled} aria-busy={busy} className={jobPrimary}>{busy?copy.saving:confirmLabel}</button></footer></form></Dialog>;
}
